//
// MathJax configuration for the LaTeX the gallery emits as `$$ ... $$` blocks
// (docs/gallery.md, generated by tools/gallery/main.cpp). pymdownx.arithmatex,
// enabled in mkdocs.yml, rewrites those blocks into the \[ ... \] / \( ... \)
// spelling MathJax expects and wraps them in an element carrying the
// "arithmatex" class; this file is the standard mkdocs-material recipe for
// wiring MathJax up to read exactly that class.
//
// The document$.subscribe callback re-typesets on every client-side
// navigation: Material's instant-loading feature swaps page content without a
// full reload, which would otherwise leave a freshly navigated-to page with
// its raw LaTeX source still showing.
window.MathJax = {
  tex: {
    inlineMath: [["\\(", "\\)"]],
    displayMath: [["\\[", "\\]"]],
    processEscapes: true,
    processEnvironments: true
  },
  options: {
    ignoreHtmlClass: ".*|",
    processHtmlClass: "arithmatex"
  }
};

document$.subscribe(() => {
  MathJax.startup.output.clearCache();
  MathJax.typesetClear();
  MathJax.texReset();
  MathJax.typesetPromise();
});
